def bell_number(n):
    # Initialize the Bell number array with zeros
    bell = [0] * (n + 1)
    bell[0] = 1  # Base case: B(0) = 1

    # Calculate Bell numbers using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            bell[i] += bell[j] * bell[i - j - 1]

    return bell[n]

