    # If n is 0, it cannot be represented as sum of non-zero powers of 2
    if n == 0:
        return False
    # If n is 1, it can be represented as 2^0
    elif n == 1:
        return True
    # If n is even, it can be represented as sum of non-zero powers of 2
    elif n % 2 == 0:
        return is_Sum_Of_Powers_Of_Two(n // 2)
    # If n is odd, it cannot be represented as sum of non-zero powers of 2
    else:
        return False
