def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = ''
    for char in message:
        if char in vowels:
            # Find the next vowel that is 2 places ahead
            next_vowel = vowels[(vowels.index(char) + 2) % len(vowels)]
            encoded_message += next_vowel
        else:
            # Swap case for non-vowels
            encoded_message += char.swapcase()
    return encoded_message

