def get_total_number_of_sequences(m, n):
    # Initialize a 2D list to store the number of sequences
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: There's one way to have a sequence of length 0 with any number
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # The number of sequences of length j with the last element i is the sum of sequences of length j-1 with the last element less than i/2
            dp[i][j] = dp[i // 2][j - 1]

    # The total number of sequences of length n with any number is the sum of sequences of length n with any number less than m
    return sum(dp[i][n] for i in range(1, m + 1))
