def max_sum_increasing_subseq(nums, i, k, j):
    # Base case: if i is out of bounds, return 0
    if i >= len(nums):
        return 0

    # If the kth element is after i, return the sum of the subsequence from i to j
    if k > i:
        return sum(nums[i:j+1])

    # Recursive case: include the kth element in the subsequence or not
    include_kth = nums[k] + max_sum_increasing_subseq(nums, i+1, k, j)
    exclude_kth = max_sum_increasing_subseq(nums, i+1, k, j)

    # Return the maximum of including or excluding the kth element
    return max(include_kth, exclude_kth)
