            if (tuples_list[i][0], tuples_list[j][1]) in bidirectional_pairs or (tuples_list[i][1], tuples_list[j][0]) in bidirectional_pairs:
                continue
            bidirectional_pairs.add((tuples_list[i][0], tuples_list[j][1]))
    return len(bidirectional_pairs)

